+pub fn contains(xs: []const i32, needle: i32) bool {
+    var lo: usize = 0;
+    var hi: usize = xs.len;
+    while (lo < hi) {
+        const mid = lo + (hi - lo) / 2;
+        if (xs[mid] == needle) return true;
+        if (xs[mid] < needle) lo = mid + 1 else hi = mid;
