+// Follow returns the target and counts one hit.
+func (s *Store) Follow(code string) (string, bool) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	t, ok := s.urls[code]
+	if ok {
+		s.hits[code]++
+	}
+	return t, ok
+}
